using System;\nusing System.Collections.Generic;\nusing System.Threading;\nusing System.Threading.Tasks;\nusing System.Security.Cryptography;\nusing System.Text;\nusing Microsoft.Extensions.Logging;\n\nnamespace MagnumOpus.Core\n{\n    public record Transaction(string Id, string From, string To, decimal Amount, string Token, DateTime Timestamp);\n\n    public class TransactionProcessor\n    {\n        private readonly ILogger<TransactionProcessor> _logger;\n        private readonly IBlockSimulator _blockSimulator;\n        private readonly ITransactionStore _store;\n\n        public TransactionProcessor(ILogger<TransactionProcessor> logger, IBlockSimulator blockSimulator, ITransactionStore store)\n        {\n            _logger = logger;\n            _blockSimulator = blockSimulator;\n            _store = store;\n        }\n\n        public async Task<bool> ProcessTransactionAsync(Transaction tx, CancellationToken ct = default)\n        {\n            _logger.LogInformation("Processing transaction {TxId}", tx.Id);\n\n            if (!ValidateTransaction(tx))\n            {\n                _logger.LogWarning("Transaction {TxId} failed validation", tx.Id);\n                return false;\n            }\n\n            var receipt = await _blockSimulator.SimulateAsync(tx, ct);\n            if (receipt.Success)\n            {\n                await _store.SaveAsync(tx, receipt, ct);\n                _logger.LogInformation("Transaction {TxId} committed in block {BlockNumber}", tx.Id, receipt.BlockNumber);\n                return true;\n            }\n\n            _logger.LogError("Transaction {TxId} failed during block simulation: {Reason}", tx.Id, receipt.FailureReason);\n            return false;\n        }\n\n        private bool ValidateTransaction(Transaction tx)\n        {\n            if (string.IsNullOrWhiteSpace(tx.From) || string.IsNullOrWhiteSpace(tx.To))\n                return false;\n            if (tx.Amount <= 0)\n                return false;\n            if (tx.Timestamp > DateTime.UtcNow.AddMinutes(5))\n                return false;\n            // Simple replay protection using hash of Id\n            using var sha = SHA256.Create();\n            var hash = sha.ComputeHash(Encoding.UTF8.GetBytes(tx.Id));\n            var checksum = BitConverter.ToString(hash).Replace("-", "").Substring(0, 8);\n            return int.TryParse(checksum, System.Globalization.NumberStyles.HexNumber, null, out _);\n        }\n    }\n\n    public interface IBlockSimulator\n    {\n        Task<BlockReceipt> SimulateAsync(Transaction tx, CancellationToken ct = default);\n    }\n\n    public record BlockReceipt(bool Success, long BlockNumber = 0, string FailureReason = null);\n\n    public interface ITransactionStore\n    {\n        Task SaveAsync(Transaction tx, BlockReceipt receipt, CancellationToken ct = default);\n    }\n\n    // In‑memory implementation for rapid prototyping\n    public class InMemoryBlockSimulator : IBlockSimulator\n    {\n        private long _currentBlock = 1;\n        private readonly Random _rnd = new();\n\n        public Task<BlockReceipt> SimulateAsync(Transaction tx, CancellationToken ct = default)\n        {\n            // Simulate processing delay\n            var delay = _rnd.Next(50, 200);\n            return Task.Delay(delay, ct).ContinueWith(_ =>\n            {\n                // 98 % success rate\n                var success = _rnd.NextDouble() < 0.98;\n                return success\n                    ? new BlockReceipt(true, Interlocked.Increment(ref _currentBlock))\n                    : new BlockReceipt(false, 0, "Random simulated failure");\n            }, ct);\n        }\n    }\n\n    public class InMemoryTransactionStore : ITransactionStore\n    {\n        private readonly List<(Transaction Tx, BlockReceipt Receipt)> _ledger = new();\n\n        public Task SaveAsync(Transaction tx, BlockReceipt receipt, CancellationToken ct = default)\n        {\n            _ledger.Add((tx, receipt));\n            return Task.CompletedTask;\n        }\n\n        // Helper for diagnostics\n        public IReadOnlyList<(Transaction Tx, BlockReceipt Receipt)> GetAll() => _ledger.AsReadOnly();\n    }\n}\n